import fs from 'fs';
import path from 'path';

// Base64 representation of the 256x256 icon (with AiroShare text)
const base64Png = '';
const pngBuffer = Buffer.from(base64Png, 'base64');

export function getDeviceIcon(size) {
  try {
    const appPath = process.env.APP_PATH || process.cwd();
    const iconPath = path.join(appPath, 'public', 'AiroShare.png');
    if (fs.existsSync(iconPath)) {
      return fs.readFileSync(iconPath);
    }
  } catch (err) {
    // Ignore and fallback to base64
  }
  return pngBuffer;
}

export default getDeviceIcon;
